-- Milestones 3–5: financial records, reusable routines, reports and notification
-- metadata. Secrets and push key material deliberately do not belong in this schema.
create table purchases(
 id uuid primary key, owner_id uuid not null references profiles(user_id), title text not null check(length(trim(title)) between 1 and 200), amount_cents integer not null check(amount_cents>0), purchase_date date not null check(purchase_date<=app.local_day()), note text not null default '' check(length(note)<=10000), linked_wishlist_id uuid, deleted_at timestamptz, revision integer not null default 1, created_at timestamptz not null default now());
create table categories(id uuid primary key default gen_random_uuid(), owner_id uuid not null references profiles(user_id), category_key text not null check(category_key in ('Clothes','Tech','Jewelry','Home items','Experiences','Travel','Other')), revision integer not null default 1, unique(owner_id,category_key));
create table wishlist_items(id uuid primary key, category_id uuid not null references categories(id), owner_id uuid not null references profiles(user_id), title text not null check(length(trim(title)) between 1 and 200), estimated_cents integer not null check(estimated_cents>0), external_url text check(external_url is null or external_url ~ '^https?://'), note text not null default '' check(length(note)<=10000), status text not null default 'active' check(status in ('active','purchased','archived')), linked_purchase_id uuid, revision integer not null default 1, created_at timestamptz not null default now());
alter table purchases add constraint purchases_wishlist_fk foreign key(linked_wishlist_id) references wishlist_items(id);
alter table wishlist_items add constraint wishlist_purchase_fk foreign key(linked_purchase_id) references purchases(id);
create table allocation_events(id uuid primary key, owner_id uuid not null references profiles(user_id), category_id uuid not null references categories(id), cents integer not null check(cents<>0), reason text not null check(reason in ('fund','move','purchase','purchase_reversal')), move_id uuid, purchase_id uuid references purchases(id), created_at timestamptz not null default now());
create table routine_templates(id uuid primary key, owner_id uuid not null references profiles(user_id), name text not null check(length(trim(name)) between 1 and 200), title text not null check(length(trim(title)) between 1 and 200), description text not null default '' check(length(description)<=10000), weekdays integer[] not null check(array_length(weekdays,1) between 1 and 7 and weekdays <@ array[1,2,3,4,5,6,7]), suggested_reward_cents integer check(suggested_reward_cents>=0), archived_at timestamptz, revision integer not null default 1, created_at timestamptz not null default now());
create table template_versions(id uuid primary key default gen_random_uuid(), template_id uuid not null references routine_templates(id), revision integer not null, snapshot jsonb not null, created_at timestamptz not null default now(), unique(template_id,revision));
create table report_preferences(owner_id uuid primary key references profiles(user_id), pending_email text check(pending_email is null or pending_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'), verified_email text check(verified_email is null or verified_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'), enabled boolean not null default false, verification_state text not null default 'unconfigured' check(verification_state in ('unconfigured','pending','verified')), revision integer not null default 1, updated_at timestamptz not null default now());
create table weekly_reports(id uuid primary key default gen_random_uuid(), owner_id uuid not null references profiles(user_id), week_start date not null, snapshot jsonb not null, source_revision integer not null default 1, status text not null default 'generated' check(status in ('generated','sent','skipped','failed')), generated_at timestamptz not null default now(), unique(owner_id,week_start));
create table report_delivery_jobs(id uuid primary key default gen_random_uuid(), owner_id uuid not null references profiles(user_id), week_start date not null, state text not null default 'pending' check(state in ('pending','leased','sent','skipped','failed')), attempts integer not null default 0, provider_id text, last_error text, unique(owner_id,week_start));
create table notification_preferences(owner_id uuid primary key references profiles(user_id), enabled boolean not null default false, revision integer not null default 1, updated_at timestamptz not null default now());
create table notification_updates(id uuid primary key default gen_random_uuid(), owner_id uuid not null references profiles(user_id), local_date date not null, kind text not null check(kind in ('morning','evening')), content jsonb not null, created_at timestamptz not null default now(), unique(owner_id,local_date,kind));
create table notification_jobs(id uuid primary key default gen_random_uuid(), owner_id uuid not null references profiles(user_id), local_date date not null, kind text not null check(kind in ('morning','evening')), state text not null default 'pending' check(state in ('pending','leased','sent','skipped','failed')), attempts integer not null default 0, last_error text, unique(owner_id,local_date,kind));

create function app.wallet_cents(p_owner uuid) returns integer language sql stable security definer set search_path=public as $$
 select coalesce((select sum(cents) from earnings where owner_id=p_owner and active),0)-coalesce((select sum(amount_cents) from purchases where owner_id=p_owner and deleted_at is null),0) $$;
create function app.allocated_cents(p_owner uuid) returns integer language sql stable security definer set search_path=public as $$ select coalesce(sum(cents),0) from allocation_events where owner_id=p_owner $$;
create function app.assert_owner(p_owner uuid) returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null or auth.uid()<>p_owner then raise exception 'Record is read-only'; end if; end $$;
create function app.queue(p_entity text,p_id text,p_revision integer) returns void language plpgsql security definer set search_path=public as $$ begin insert into sheet_jobs(entity,record_id,revision) values(p_entity,p_id,p_revision) on conflict do nothing; end $$;

create function public.save_purchase(p_id uuid,p_title text,p_amount_cents integer,p_date date,p_note text default '',p_wishlist uuid default null,p_expected_revision integer default null) returns uuid language plpgsql security definer set search_path=public as $$
declare old purchases%rowtype; row purchases%rowtype; item wishlist_items%rowtype;
begin
 if auth.uid() is null or p_id is null or length(trim(p_title)) not between 1 and 200 or p_amount_cents<=0 or p_date>app.local_day() or length(p_note)>10000 then raise exception 'Invalid purchase'; end if;
 select * into old from purchases where id=p_id for update;
 if old.id is not null and (old.owner_id<>auth.uid() or old.deleted_at is not null or old.revision<>p_expected_revision) then raise exception 'Purchase changed or read-only'; end if;
 if p_wishlist is not null then select * into item from wishlist_items where id=p_wishlist for update; if item.id is null or item.owner_id<>auth.uid() or item.status<>'active' then raise exception 'Wishlist item is unavailable'; end if; end if;
 if old.id is null then insert into purchases(id,owner_id,title,amount_cents,purchase_date,note,linked_wishlist_id) values(p_id,auth.uid(),trim(p_title),p_amount_cents,p_date,p_note,p_wishlist) returning * into row; else update purchases set title=trim(p_title),amount_cents=p_amount_cents,purchase_date=p_date,note=p_note,revision=revision+1 where id=p_id returning * into row; end if;
 if p_wishlist is not null then update wishlist_items set status='purchased',linked_purchase_id=p_id,revision=revision+1 where id=p_wishlist; insert into allocation_events(id,owner_id,category_id,cents,reason,purchase_id) select gen_random_uuid(),auth.uid(),category_id,-least(coalesce((select sum(cents) from allocation_events where category_id=item.category_id),0),p_amount_cents),'purchase',p_id from wishlist_items where id=p_wishlist; end if;
 perform app.audit_change(auth.uid(),'purchases',p_id::text,case when old.id is null then null else to_jsonb(old) end,to_jsonb(row)); return p_id;
end $$;
create function public.delete_purchase(p_id uuid,p_expected_revision integer) returns void language plpgsql security definer set search_path=public as $$
declare old purchases%rowtype; begin select * into old from purchases where id=p_id for update; if old.owner_id<>auth.uid() or old.deleted_at is not null or old.revision<>p_expected_revision then raise exception 'Purchase changed or read-only'; end if; update purchases set deleted_at=now(),revision=revision+1 where id=p_id; if old.linked_wishlist_id is not null then update wishlist_items set status='active',linked_purchase_id=null,revision=revision+1 where id=old.linked_wishlist_id; insert into allocation_events(id,owner_id,category_id,cents,reason,purchase_id) select gen_random_uuid(),auth.uid(),category_id,-cents,'purchase_reversal',p_id from allocation_events where purchase_id=p_id and reason='purchase'; end if; perform app.audit_change(auth.uid(),'purchases',p_id::text,to_jsonb(old),(select to_jsonb(p) from purchases p where id=p_id)); end $$;
create function public.save_wishlist_item(p_id uuid,p_category uuid,p_title text,p_estimated integer,p_url text default null,p_note text default '',p_expected_revision integer default null) returns uuid language plpgsql security definer set search_path=public as $$
declare old wishlist_items%rowtype; row wishlist_items%rowtype; begin if p_id is null or length(trim(p_title)) not between 1 and 200 or p_estimated<=0 or length(p_note)>10000 or (p_url is not null and p_url !~ '^https?://') then raise exception 'Invalid goal item'; end if; perform app.assert_owner((select owner_id from categories where id=p_category)); select * into old from wishlist_items where id=p_id for update; if old.id is not null and (old.owner_id<>auth.uid() or old.revision<>p_expected_revision) then raise exception 'Goal item changed or read-only'; end if; if old.id is null then insert into wishlist_items(id,category_id,owner_id,title,estimated_cents,external_url,note) values(p_id,p_category,auth.uid(),trim(p_title),p_estimated,p_url,p_note) returning * into row; else update wishlist_items set category_id=p_category,title=trim(p_title),estimated_cents=p_estimated,external_url=p_url,note=p_note,revision=revision+1 where id=p_id returning * into row; end if; perform app.audit_change(auth.uid(),'wishlist_items',p_id::text,case when old.id is null then null else to_jsonb(old) end,to_jsonb(row)); return p_id; end $$;
create function public.fund_category(p_category uuid,p_cents integer,p_move_from uuid default null) returns void language plpgsql security definer set search_path=public as $$
declare owner uuid; move uuid:=gen_random_uuid(); begin select owner_id into owner from categories where id=p_category for update; perform app.assert_owner(owner); if p_cents<=0 then raise exception 'Amount must be positive'; end if; if p_move_from is null and app.allocated_cents(owner)+p_cents>greatest(app.wallet_cents(owner),0) then raise exception 'Not enough unallocated balance'; end if; if p_move_from is not null then perform app.assert_owner((select owner_id from categories where id=p_move_from)); insert into allocation_events(id,owner_id,category_id,cents,reason,move_id) values(gen_random_uuid(),owner,p_move_from,-p_cents,'move',move); end if; insert into allocation_events(id,owner_id,category_id,cents,reason,move_id) values(gen_random_uuid(),owner,p_category,p_cents,case when p_move_from is null then 'fund' else 'move' end,move); perform app.audit_change(owner,'allocation_events',move::text,null,jsonb_build_object('category_id',p_category,'cents',p_cents,'revision',1)); end $$;
create function public.save_template(p_id uuid,p_name text,p_title text,p_description text,p_weekdays integer[],p_reward integer default null,p_expected_revision integer default null) returns uuid language plpgsql security definer set search_path=public as $$
declare old routine_templates%rowtype; row routine_templates%rowtype; begin if p_id is null or length(trim(p_name)) not between 1 and 200 or length(trim(p_title)) not between 1 and 200 or length(p_description)>10000 or array_length(p_weekdays,1) not between 1 and 7 or not p_weekdays <@ array[1,2,3,4,5,6,7] or p_reward<0 then raise exception 'Invalid template'; end if; select * into old from routine_templates where id=p_id for update; if old.id is not null and (old.owner_id<>auth.uid() or old.revision<>p_expected_revision) then raise exception 'Template changed or read-only'; end if; if old.id is null then insert into routine_templates(id,owner_id,name,title,description,weekdays,suggested_reward_cents) values(p_id,auth.uid(),trim(p_name),trim(p_title),p_description,p_weekdays,p_reward) returning * into row; else update routine_templates set name=trim(p_name),title=trim(p_title),description=p_description,weekdays=p_weekdays,suggested_reward_cents=p_reward,revision=revision+1 where id=p_id returning * into row; end if; insert into template_versions(template_id,revision,snapshot) values(row.id,row.revision,to_jsonb(row)); perform app.audit_change(auth.uid(),'routine_templates',row.id::text,case when old.id is null then null else to_jsonb(old) end,to_jsonb(row)); return row.id; end $$;
create function public.save_report_preference(p_email text,p_enabled boolean) returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null or p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'Enter a valid email address'; end if; insert into report_preferences(owner_id,pending_email,enabled,verification_state) values(auth.uid(),lower(trim(p_email)),false,'pending') on conflict(owner_id) do update set pending_email=excluded.pending_email,enabled=false,verification_state='pending',revision=report_preferences.revision+1,updated_at=now(); perform app.audit_change(auth.uid(),'report_preferences',auth.uid()::text,null,(select to_jsonb(x) from report_preferences x where owner_id=auth.uid())); end $$;
create function public.set_notification_preference(p_enabled boolean) returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Sign in required'; end if; insert into notification_preferences(owner_id,enabled) values(auth.uid(),p_enabled) on conflict(owner_id) do update set enabled=excluded.enabled,revision=notification_preferences.revision+1,updated_at=now(); perform app.audit_change(auth.uid(),'notification_preferences',auth.uid()::text,null,(select to_jsonb(x) from notification_preferences x where owner_id=auth.uid())); end $$;
create function public.ensure_categories() returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Sign in required'; end if; insert into categories(owner_id,category_key) select auth.uid(),x from unnest(array['Clothes','Tech','Jewelry','Home items','Experiences','Travel','Other']) x on conflict(owner_id,category_key) do nothing; end $$;
create view weekly_insight_rows with (security_invoker=true) as select t.owner_id,t.id task_id,t.title,d.local_date::date local_date,app.due(t.id,d.local_date::date) due,coalesce(c.completed,false) completed from tasks t cross join lateral generate_series(t.start_date,app.local_day(),'1 day') d(local_date) left join completions c on c.task_id=t.id and c.local_date=d.local_date::date;

alter table purchases enable row level security; alter table categories enable row level security; alter table wishlist_items enable row level security; alter table allocation_events enable row level security; alter table routine_templates enable row level security; alter table template_versions enable row level security; alter table report_preferences enable row level security; alter table weekly_reports enable row level security; alter table report_delivery_jobs enable row level security; alter table notification_preferences enable row level security; alter table notification_updates enable row level security; alter table notification_jobs enable row level security;
create policy read_purchases on purchases for select to authenticated using(app.same_group(auth.uid(),owner_id)); create policy read_categories on categories for select to authenticated using(app.same_group(auth.uid(),owner_id)); create policy read_items on wishlist_items for select to authenticated using(app.same_group(auth.uid(),owner_id)); create policy read_allocations on allocation_events for select to authenticated using(app.same_group(auth.uid(),owner_id)); create policy read_templates on routine_templates for select to authenticated using(app.same_group(auth.uid(),owner_id)); create policy read_template_versions on template_versions for select to authenticated using(exists(select 1 from routine_templates t where t.id=template_id and app.same_group(auth.uid(),t.owner_id))); create policy read_preferences on report_preferences for select to authenticated using(app.same_group(auth.uid(),owner_id)); create policy read_reports on weekly_reports for select to authenticated using(app.same_group(auth.uid(),owner_id)); create policy read_notification_preferences on notification_preferences for select to authenticated using(app.same_group(auth.uid(),owner_id)); create policy read_updates on notification_updates for select to authenticated using(app.same_group(auth.uid(),owner_id));
revoke all on purchases,categories,wishlist_items,allocation_events,routine_templates,template_versions,report_preferences,weekly_reports,report_delivery_jobs,notification_preferences,notification_updates,notification_jobs from anon,authenticated;
grant select on purchases,categories,wishlist_items,allocation_events,routine_templates,template_versions,report_preferences,weekly_reports,notification_preferences,notification_updates,weekly_insight_rows to authenticated;
revoke execute on function public.save_purchase(uuid,text,integer,date,text,uuid,integer),public.delete_purchase(uuid,integer),public.save_wishlist_item(uuid,uuid,text,integer,text,text,integer),public.fund_category(uuid,integer,uuid),public.save_template(uuid,text,text,text,integer[],integer,integer),public.save_report_preference(text,boolean),public.set_notification_preference(boolean),public.ensure_categories() from public,anon;
grant execute on function public.save_purchase(uuid,text,integer,date,text,uuid,integer),public.delete_purchase(uuid,integer),public.save_wishlist_item(uuid,uuid,text,integer,text,text,integer),public.fund_category(uuid,integer,uuid),public.save_template(uuid,text,text,text,integer[],integer,integer),public.save_report_preference(text,boolean),public.set_notification_preference(boolean),public.ensure_categories() to authenticated;
